class Preprocessor:
    def load(self, path):
        tar = tarfile.open(path)
        tar.extractall(path='../')
        return self.preprocess(os.path.join('.', tar.getnames()), tar.getmembers())

    def preprocess(self, dir_path, members):
        data = []
        for member in members:
            fname = member.name
            with open(os.path.join(dir_path, fname), 'r') as f:
                data.append(f.read())
        return data

    def process(self, data):
        return [item.upper() for item in data]

