def can_react(post):
    if post is None:
        raise ValueError("Post cannot be None")

    if post.comments < 0:
        return "disable_comment_reactions"

    if post.likes < 0:
        return "disable_like_reactions"

    if post.favorites < 0:
        return "disable_favorite_reactions"

    if post.videos < 0:
        return "disable_video_reaction"

    if post.story < 0:
        return "disable_story_reaction"

    if post.draft < 0:
        return "disable_draft_reaction"

    if post.tagged < 0:
        return "disable_tag_reactions"

    return "enable_all_reactions"

